package org.acme.geoindex;

public class GeoIndex {
    public int nearest(int[] points, int x) {
        int best = points[0];
        for (int p : points) {
            if (Math.abs(p - x) < Math.abs(best - x)) {
                best = p;
            }
        }
        return best;
    }
}

package org.acme.geoindex;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class GeoIndexTest {
    @Test
    void findsNearest() {
        assertEquals(5, new GeoIndex().nearest(new int[] {1, 5, 9}, 6));
    }
}
